/* HARZWORKS LICHTENSTEIN 40 – ausklappbare Gravurvorschau, Version 17: Alex Brush; Ecwid file upload field targeting Bild Vorschau */
(function () {
  'use strict';
  if (window.__HW_L40_V6__) return;
  window.__HW_L40_V6__ = true;

  // Explicitly register the web font independently of Ecwid's cached CSS.
  const HW_FONT_URL = 'https://fonts.googleapis.com/css2?family=Alex+Brush&display=swap';
  if (!document.getElementById('hw-l40-alexbrush-font-v15')) {
    const link = document.createElement('link');
    link.id = 'hw-l40-alexbrush-font-v15';
    link.rel = 'stylesheet';
    link.href = HW_FONT_URL;
    document.head.appendChild(link);
  }
  if (!document.getElementById('hw-l40-alexbrush-override-v15')) {
    const style = document.createElement('style');
    style.id = 'hw-l40-alexbrush-override-v15';
    style.textContent = '.hw-l40-disclosure .hw-l40-names, .hw-l40-lightbox .hw-l40-names, .hw-l40-disclosure .hw-l40-names tspan, .hw-l40-lightbox .hw-l40-names tspan { font-family: "Alex Brush", cursive !important; font-style: normal !important; font-weight: 500 !important; }';
    document.head.appendChild(style);
  }
  const PRODUCT = '871120612';
  const MONTHS = ['JANUAR','FEBRUAR','MÄRZ','APRIL','MAI','JUNI','JULI',
                  'AUGUST','SEPTEMBER','OKTOBER','NOVEMBER','DEZEMBER'];
  const BACKGROUND = 'data:image/jpeg;base64,';
  let root = null, fields = [], previousUrl = location.href;
  let lastValues = null;

  function onProduct() {
    return location.href.includes('-p' + PRODUCT) ||
      /[?&#](?:id|product)=871120612(?:[&#]|$)/.test(location.href);
  }
  function tidy(v) { return String(v || '').replace(/\s+/g, ' ').trim(); }

  function findField(label) {
    for (const el of document.querySelectorAll(
      'label,.details-product-option__title,.details-product-option__name,.form-control__label,span,div')) {
      if (el.children.length > 3 || tidy(el.textContent) !== label) continue;
      if (el.htmlFor) {
        const input = document.getElementById(el.htmlFor);
        if (input && input.matches('input,textarea')) return input;
      }
      let parent = el;
      for (let i=0; i<5 && parent; i++, parent=parent.parentElement) {
        const matches = [...parent.querySelectorAll(
          'input[type="text"],input[type="date"],input:not([type]),textarea')]
          .filter(input => input.getClientRects().length);
        if (matches.length === 1) return matches[0];
      }
    }
    return null;
  }
  function formattedDate(v) {
    const s = tidy(v);
    let match = s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})$/);
    if (match && +match[2]>=1 && +match[2]<=12)
      return `${+match[1]}. ${MONTHS[+match[2]-1]} ${match[3]}`;
    match = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (match && +match[2]>=1 && +match[2]<=12)
      return `${+match[3]}. ${MONTHS[+match[2]-1]} ${match[1]}`;
    return s.toLocaleUpperCase('de-DE');
  }
  function fitText(node, value, size, maxWidth) {
    node.textContent = value;
    node.setAttribute('font-size', size);
    node.removeAttribute('textLength');
    node.removeAttribute('lengthAdjust');
    try {
      if (node.getComputedTextLength() > maxWidth) {
        node.setAttribute('textLength', maxWidth);
        node.setAttribute('lengthAdjust', 'spacingAndGlyphs');
      }
    } catch(e) {}
  }
  function setCalligraphy(node, first, second) {
    // One continuous Alex Brush text run; no individually enlarged capitals.
    fitText(node, `${first} & ${second}`, 99, 585);
  }
  function update() {
    if (!root || fields.length !== 3) return;
    const a = tidy(fields[0].value) || 'Anna';
    const b = tidy(fields[1].value) || 'Markus';
    const d = formattedDate(fields[2].value) || 'HOCHZEITSDATUM EINGEBEN';
    setCalligraphy(root.querySelector('.hw-l40-names'), a, b);
    // Same Montserrat date lettering as before, increased 15% from 32 to 36.8.
    fitText(root.querySelector('.hw-l40-date'), d, 36.8, 435);
    fitText(root.querySelector('.hw-l40-initials'),
      `${a[0].toLocaleUpperCase('de-DE')}&${b[0].toLocaleUpperCase('de-DE')}`, 49, 112);
    // If the customer keeps the lightbox open, synchronize its SVG immediately.
    const popupSvg = document.querySelector('.hw-l40-lightbox .hw-l40-lightbox-image svg');
    const originalSvg = root.querySelector('.hw-l40-svg');
    if (popupSvg && originalSvg) {
      for (const klass of ['hw-l40-names','hw-l40-date','hw-l40-initials']) {
        const source = originalSvg.querySelector('.' + klass);
        const target = popupSvg.querySelector('.' + klass);
        if (source && target) target.replaceWith(source.cloneNode(true));
      }
    }
  }
  function createPanel() {
    const el = document.createElement('section');
    el.className = 'hw-l40-disclosure';
    el.innerHTML = `
      <button type="button" class="hw-l40-toggle" aria-expanded="false">
        <span class="hw-l40-toggle-label"><span class="hw-l40-eye" aria-hidden="true">◉</span> Deine Gravur ansehen</span>
        <span class="hw-l40-chevron" aria-hidden="true">⌄</span>
      </button>
      <div class="hw-l40-panel" hidden>
        <p class="hw-l40-heading">Deine persönliche Gravur · Live-Vorschau</p>
        <div class="hw-l40-viewport"><div class="hw-l40-zoomable">
          <svg class="hw-l40-svg" viewBox="0 0 1254 1254"
               xmlns="http://www.w3.org/2000/svg" role="img"
               aria-label="Personalisierte Hochzeitsuhr">
            <image href="${BACKGROUND}" width="1254" height="1254"/>
            <text class="hw-l40-initials" x="377" y="785" text-anchor="middle"
                  transform="rotate(-12 377 785)" font-size="49">A&amp;M</text>
            <text class="hw-l40-names" x="774" y="795" text-anchor="middle"
                  font-size="99">Anna &amp; Markus</text>
            <text class="hw-l40-date" x="774" y="853" text-anchor="middle"
                  font-size="36.8">14. SEPTEMBER 2024</text>
          </svg>
        </div></div>
        <div class="hw-l40-actions">
          <button type="button" data-hw-zoom="-1" aria-label="Verkleinern">−</button>
          <span class="hw-l40-percent">100 %</span>
          <button type="button" data-hw-zoom="1" aria-label="Vergrößern">+</button>
          <button type="button" data-hw-zoom="reset">Zurücksetzen</button>
        </div>
        <p class="hw-l40-notice">Digitale Gravurvorschau. Holzstruktur und Gravur
        können vom fertigen Unikat abweichen.</p>
      </div>`;
    const toggle = el.querySelector('.hw-l40-toggle');
    const panel = el.querySelector('.hw-l40-panel');
    toggle.addEventListener('click', function() {
      const open = panel.hidden;
      panel.hidden = !open;
      toggle.setAttribute('aria-expanded', String(open));
      el.querySelector('.hw-l40-toggle-label').textContent =
        open ? 'Gravurvorschau schließen' : 'Deine Gravur ansehen';
      if (open) {
        update();
        if (document.fonts && document.fonts.ready)
          document.fonts.ready.then(() => { if (root === el) update(); });
      }
    });
    let zoom = 1;
    el.querySelectorAll('[data-hw-zoom]').forEach(btn =>
      btn.addEventListener('click', function() {
        const action = btn.dataset.hwZoom;
        zoom = action === 'reset' ? 1 :
          Math.max(1, Math.min(2.5, zoom + Number(action)*0.25));
        el.querySelector('.hw-l40-zoomable').style.transform = `scale(${zoom})`;
        el.querySelector('.hw-l40-percent').textContent = `${Math.round(100*zoom)} %`;
      }));
    return el;
  }

  function enablePopup(section) {
    const viewport = section.querySelector('.hw-l40-viewport');
    if (!viewport) return;
    viewport.setAttribute('role', 'button');
    viewport.setAttribute('tabindex', '0');
    viewport.setAttribute('aria-label', 'Personalisierte Uhr groß ansehen');

    function openPopup() {
      update();
      const overlay = document.createElement('div');
      overlay.className = 'hw-l40-lightbox';
      overlay.setAttribute('role', 'dialog');
      overlay.setAttribute('aria-modal', 'true');
      overlay.setAttribute('aria-label', 'Vergrößerte Gravurvorschau');
      overlay.innerHTML = `
        <div class="hw-l40-lightbox-content">
          <button type="button" class="hw-l40-lightbox-close"
                  aria-label="Vorschau schließen">×</button>
          <div class="hw-l40-lightbox-image"></div>
          <div class="hw-l40-lightbox-controls">
            <button type="button" data-popup-zoom="-1" aria-label="Verkleinern">−</button>
            <span class="hw-l40-popup-percent">100 %</span>
            <button type="button" data-popup-zoom="1" aria-label="Vergrößern">+</button>
            <button type="button" data-popup-zoom="reset">Zurücksetzen</button>
          </div>
        </div>`;
      const imageArea = overlay.querySelector('.hw-l40-lightbox-image');
      const svgClone = section.querySelector('.hw-l40-svg').cloneNode(true);
      imageArea.append(svgClone);
      const previousOverflow = document.body.style.overflow;
      document.body.style.overflow = 'hidden';
      document.body.append(overlay);
      let popupZoom = 1;
      const closeButton = overlay.querySelector('.hw-l40-lightbox-close');
      function closePopup() {
        overlay.remove();
        document.body.style.overflow = previousOverflow;
        document.removeEventListener('keydown', onKey);
        viewport.focus({preventScroll:true});
      }
      function onKey(e) {
        if (e.key === 'Escape') closePopup();
      }
      closeButton.addEventListener('click', closePopup);
      overlay.addEventListener('click', e => {
        if (e.target === overlay) closePopup();
      });
      document.addEventListener('keydown', onKey);
      overlay.querySelectorAll('[data-popup-zoom]').forEach(btn => {
        btn.addEventListener('click', () => {
          const action = btn.dataset.popupZoom;
          popupZoom = action === 'reset' ? 1 :
            Math.max(1, Math.min(3, popupZoom + Number(action) * 0.25));
          svgClone.style.transform = `scale(${popupZoom})`;
          overlay.querySelector('.hw-l40-popup-percent').textContent =
            Math.round(popupZoom * 100) + ' %';
        });
      });
      closeButton.focus();
    }
    viewport.addEventListener('click', openPopup);
    viewport.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        openPopup();
      }
    });
  }

  // Experimental Ecwid file-option integration. The browser may attach a file;
  // Ecwid must still confirm processing it on a test order.
  let uploadTimer = 0, uploadInProgress = false, lastAttachedKey = '';
  window.HARZWORKS_uploadStatus = 'Noch kein Uploadversuch';
  function uploadField() {
    // Identify the Ecwid option *container*, never a numbered file input.
    // The customer's configured field currently displays as "Bild Vorschau".
    const options = [...document.querySelectorAll(
      '.details-product-option, .ecwid-productBrowser-details-option, [class*="details-product-option"]'
    )];
    const matches = options.filter(option => {
      const title = option.querySelector(
        '.details-product-option__title, .details-product-option__name, label, [class*="option__title"], [class*="option__name"]'
      );
      const text = (title ? title.textContent : option.textContent).replace(/\s+/g,' ').trim().toLowerCase();
      return /(?:bild\s*vorschau|gravurvorschau)/i.test(text) &&
        option.querySelectorAll('input[type="file"]').length === 1;
    });
    if (matches.length === 1) return matches[0].querySelector('input[type="file"]');
    // Ecwid themes sometimes render option headings separately; find nearest
    // option ancestor from a precisely matching label or text node.
    const headings = [...document.querySelectorAll('label, [class*="option__title"], [class*="option__name"]')]
      .filter(el => /^(bild\s*vorschau|gravurvorschau)\s*\*?$/i.test(
        el.textContent.replace(/\s+/g,' ').trim()));
    for (const heading of headings) {
      let parent=heading.parentElement;
      for (let i=0; parent && i<7; i++,parent=parent.parentElement) {
        const inputs=parent.querySelectorAll('input[type="file"]');
        if (inputs.length === 1) return inputs[0];
        if (inputs.length > 1) break;
      }
    }
    return null;
  }
  function drawPreviewPng() {
    return new Promise((resolve,reject) => {
      const bg = new Image();
      bg.onload = async () => {
        try {
          if (document.fonts && document.fonts.load)
            await document.fonts.load('99px "Alex Brush"');
          const canvas=document.createElement('canvas'); canvas.width=1254; canvas.height=1254;
          const ctx=canvas.getContext('2d');
          ctx.drawImage(bg,0,0,1254,1254);
          const a=tidy(fields[0].value), b=tidy(fields[1].value), date=formattedDate(fields[2].value);
          const write=(value,font,x,y,maxWidth) => {
            ctx.save(); ctx.fillStyle='#26140d'; ctx.textAlign='center';
            ctx.textBaseline='alphabetic'; ctx.font=font;
            ctx.fillText(value,x,y,maxWidth); ctx.restore();
          };
          ctx.save(); ctx.translate(377,785); ctx.rotate(-12*Math.PI/180);
          ctx.fillStyle='#2b170f'; ctx.textAlign='center';
          ctx.font='italic 49px Georgia, serif';
          ctx.fillText(a[0].toUpperCase()+'&'+b[0].toUpperCase(),0,0,112); ctx.restore();
          write(a+' & '+b,'99px "Alex Brush", cursive',774,795,585);
          write(date,'500 36.8px Montserrat, Arial, sans-serif',774,853,435);
          canvas.toBlob(blob=>blob?resolve(blob):reject(Error('PNG konnte nicht erzeugt werden')),'image/png');
        } catch(error) { reject(error); }
      };
      bg.onerror=()=>reject(Error('Uhrenbild konnte nicht geladen werden'));
      bg.src=BACKGROUND;
    });
  }
  async function attachPreview() {
    if (uploadInProgress || !root || !root.isConnected || fields.length!==3 ||
        fields.some(f=>!tidy(f.value))) return;
    const upload=uploadField();
    if (!upload) {
      window.HARZWORKS_uploadStatus = 'Uploadfeld Bild Vorschau nicht eindeutig erkannt';
      console.warn('[HARZWORKS]', window.HARZWORKS_uploadStatus);
      return;
    }
    const key=fields.map(f=>f.value).join('|');
    if (key===lastAttachedKey) return;
    uploadInProgress=true;
    try {
      const blob=await drawPreviewPng();
      if (!root || !root.isConnected || !upload.isConnected || key!==fields.map(f=>f.value).join('|')) return;
      const f=new File([blob],'HARZWORKS_LICHTENSTEIN40_Gravurvorschau.png',{type:'image/png'});
      const transfer=new DataTransfer(); transfer.items.add(f);
      upload.files=transfer.files;
      upload.dispatchEvent(new Event('input',{bubbles:true}));
      upload.dispatchEvent(new Event('change',{bubbles:true}));
      // Ecwid may replace/reset the file input after it accepts the file.
      // This alone is NOT a confirmation of storage in the order.
      window.HARZWORKS_uploadStatus = 'PNG an Ecwid übergeben – Vorschaubild und Testbestellung prüfen';
      lastAttachedKey=key;
      console.info('[HARZWORKS] Gravurvorschau an Ecwid-Dateifeld übergeben; bitte im Testauftrag prüfen.');
    } catch(e) {
      window.HARZWORKS_uploadStatus = 'Uploadfehler: ' + e.message;
      console.warn('[HARZWORKS] Automatische Bildübergabe nicht möglich:',e);
    } finally { uploadInProgress=false; }
  }
  function queuePreviewUpload() {
    clearTimeout(uploadTimer);
    uploadTimer=setTimeout(attachPreview,900);
  }
  function destroy() {
    if (root) root.remove();
    root = null;
    fields = [];
    lastValues = null;
    lastAttachedKey = '';
    clearTimeout(uploadTimer);
  }
  function mount() {
    if (!onProduct()) { destroy(); return; }
    if (root && root.isConnected && fields.every(f => f.isConnected)) return;
    if (root) destroy();
    const found = ['Name 1','Name 2','Hochzeitsdatum'].map(findField);
    if (found.some(f => !f)) return;
    // The button is inserted immediately after the DATE option, ahead of packaging.
    const dateField = found[2];
    const dateOption = dateField.closest('.details-product-option,.ecwid-productBrowser-details-option,[class*="product-option"],[class*="ProductOption"]');
    let anchor = dateOption;
    if (!anchor || anchor.contains(found[0]) || anchor.contains(found[1]))
      anchor = dateField.parentElement;
    if (!anchor || !anchor.parentElement) return;
    root = createPanel();
    enablePopup(root);
    fields = found;
    lastValues = null;
    if (document.fonts && document.fonts.load) {
      document.fonts.load('500 48px "Alex Brush"').then(() => {
        if (root && root.isConnected) update();
      }).catch(() => {});
    }

    anchor.insertAdjacentElement('afterend', root);
    fields.forEach(input => {
      input.addEventListener('input', update);
      input.addEventListener('change', update);
      input.addEventListener('change', queuePreviewUpload);
      input.addEventListener('input', queuePreviewUpload);
      // Kalenderauswahl kann über den Browser auch erst beim Schließen aktualisiert werden.
      input.addEventListener('blur', update);
    });
    update();
    lastValues = fields.map(f => f.value);
    queuePreviewUpload();
  }
  // Ecwid's calendar may set input.value programmatically without firing
  // an input/change event. A value-only check keeps rendering stable.
  setInterval(() => {
    if (!root || !root.isConnected || fields.length !== 3 ||
        fields.some(f => !f.isConnected)) return;
    const values = fields.map(f => f.value);
    if (!lastValues || values.some((v, i) => v !== lastValues[i])) {
      lastValues = values;
      update();
      queuePreviewUpload();
    }
  }, 250);
  if (document.readyState === 'loading')
    document.addEventListener('DOMContentLoaded', mount);
  else mount();
  if (window.Ecwid && Ecwid.OnPageLoaded)
    Ecwid.OnPageLoaded.add(() => { destroy(); mount(); });
  window.addEventListener('popstate', () => { destroy(); mount(); });
  window.addEventListener('hashchange', () => { destroy(); mount(); });
  setInterval(() => {
    if (location.href !== previousUrl) {
      previousUrl = location.href;
      destroy();
    }
    if (!root || !root.isConnected || fields.some(f => !f.isConnected)) mount();
  }, 1200);
})();
